// Shapes returned by the platform router and the engine, taken from the published API v1 contracts
// (api/*.openapi.json, written by `python -m autology openapi --write`; types generated by `npm run generate:api`).
// Nothing here is hand-typed except ModelDocument, which the engine's strict ontology schema defines.

import type { components as EngineComponents } from "./generated/engine";
import type { components as PlatformComponents } from "./generated/platform";

type E = EngineComponents["schemas"];
type P = PlatformComponents["schemas"];
// the declared properties of a schema, without the open "additionalProperties" index signature
type Known<T> = { [K in keyof T as string extends K ? never : K]: T[K] };

export type Stage = P["UseCase"]["stage"];
export type Me = P["Me"];
export type StageEvent = P["StageEvent"];
export type UseCase = P["UseCase"];
export type Check = P["Check"];
export type CheckResult = P["CheckResult"];
export type MoveResult = P["MoveResult"];
export type Template = P["Template"];
export type ApiErrorBody = P["Error"];

export type OntologySummary = E["OntologySummary"];

// -- model design ---------------------------------------------------------------------------------------------
export type ModelDocument = Record<string, any>;  // an ontology document, as the engine's strict schema defines it

export type Problem = E["Problem"];
export type Validation = E["Validation"];
export type ValidationResult = E["ValidationResult"];
export type Question = E["Question"];
export type Draft = E["Draft"] & { document: ModelDocument };
export type ProposalItem = E["ProposalItem"] & { value: any };  // an entity, relationship, action or rule body
export type Proposal = Omit<Known<E["Proposal"]>, "items"> & { items: ProposalItem[] };
